// ============================================================
// conteo.js — la app de Conteo, ahora dentro del Armador.
// Contar stock (escaneo, búsqueda, bultos, corregir posición, eliminar),
// Ingreso de proveedor con lectura de remitos, Compras y Armar pedido.
// Se carga bajo demanda desde index.html (import('./conteo.js')).
// Todos los elementos de pantalla de este módulo llevan el prefijo "cn_".
// ============================================================
export function iniciarConteo(ctx) {
  const {
    db, doc, getDoc, setDoc, deleteDoc, runTransaction, collection, collectionGroup, query, where, orderBy, limit, getDocs,
    serverTimestamp, increment, escapeHtml, mostrarToast, persona, esGestion, abrirConteo
  } = ctx;

      // ---------------- DATOS DE MARCA PARA LA ORDEN DE COMPRA ----------------
      // Completá/cambiá acá si hace falta ajustar algo (nombre, colores).
      const NOMBRE_EMPRESA = "Campo Verde";
      const COLOR_MARCA_VERDE = [83, 133, 75];   // extraído del logo
      const COLOR_MARCA_AMARILLO = [253, 214, 61]; // extraído del logo
      const LOGO_BASE64 = "data:image/png;base64,";

      // ⚠️ CONFIGURACIÓN: clave de API de Google Cloud Vision, del MISMO
      // proyecto de Firebase (armador-de-pedidos-secos-119b3). Pasos:
      // 1) Google Cloud Console > el proyecto > "APIs y servicios" > "Biblioteca"
      //    > buscar "Cloud Vision API" > Habilitar.
      // 2) "APIs y servicios" > "Credenciales" > "Crear credenciales" > "Clave de API".
      // 3) Restringila: "Restricciones de la aplicación" > "Sitios web" > agregar
      //    el dominio donde vive esta app (ej: https://logisticacentralcv-sys.github.io/*).
      //    "Restricciones de API" > limitarla solo a "Cloud Vision API".
      // 4) Pegá la clave acá abajo, reemplazando el texto de ejemplo.
      const VISION_API_KEY = "AIzaSyDXwiHQF1zdQmNWsWJM8xnnObuZDTdsDSY";

      let html5QrCode = null;
      let html5QrCodeBulto = null;
      let productoActual = null;
      let sesion = [];
      let ultimaPosicion = "";
      let esBultoActual = false;
      let unidadesPorBultoActual = 1;
      let posicionesDisponibles = [];
      let modoProveedor = false;
      let proveedorActivo = "";
      let productosDelProveedorActivo = null; // null = sin filtrar (usa Firestore); array = filtrado en memoria
      let indiceProductosProveedor = null; // índice de tokens con pesado por rareza, para el matching del remito
      let aliasesProveedorActivo = {}; // textoNormalizado -> {codigo, producto} — lo que ya se corrigió antes para este proveedor
      let proveedoresYaListados = false;

      const productoBox = document.getElementById('cn_productoBox');

      // ---------------- MODO INGRESO DE PROVEEDOR ----------------
      // En este modo, en vez de pedir la posición (como en el conteo normal,
      // donde tiene sentido ir físicamente pasillo por pasillo), se suma
      // directo a la posición principal que el producto ya tenga guardada —
      // así cargar un remito es escanear + cantidad, sin pensar en dónde va.
      // Si el producto es nuevo (nunca se contó, no tiene posición principal
      // todavía), simplemente pide la posición como en el modo normal.
      // Interruptor "Contar" / "Ingreso de proveedor" (está arriba del panel de conteo)
      function aplicarModoProveedor_(activo) {
        modoProveedor = activo;
        document.getElementById('cn_bannerModoProveedor').style.display = activo ? 'block' : 'none';
        document.getElementById('cn_btnModoContar').classList.toggle('activo', !activo);
        document.getElementById('cn_btnModoProveedor').classList.toggle('activo', activo);
        document.getElementById('cn_tituloSesion').textContent = activo ? 'Ingresado de proveedor en esta sesión' : 'Contado en esta sesión';
        document.getElementById('cn_btnConfirmar').textContent = activo ? '🚚 Sumar ingreso' : '✔ Confirmar y guardar';
        if (activo && !proveedoresYaListados) cargarListaProveedores();
        if (productoActual) mostrarProducto(productoActual); // recalcula la posición sugerida si hay un producto abierto
      }
      document.getElementById('cn_btnModoProveedor').addEventListener('click', () => aplicarModoProveedor_(true));
      document.getElementById('cn_btnModoContar').addEventListener('click', () => aplicarModoProveedor_(false));

      async function cargarListaProveedores() {
        proveedoresYaListados = true;
        try {
          const snap = await getDocs(collection(db, 'proveedores'));
          const nombres = [];
          snap.forEach(d => nombres.push(d.data().nombre || d.id));
          nombres.sort((a, b) => a.localeCompare(b, 'es'));
          const select = document.getElementById('cn_selectProveedorActivo');
          nombres.forEach(nombre => {
            const opt = document.createElement('option');
            opt.value = nombre;
            opt.textContent = nombre;
            select.appendChild(opt);
          });
        } catch (err) {
          console.error('Error cargando proveedores', err);
        }
      }

      // Al elegir un proveedor, se traen sus productos UNA vez (consulta
      // simple por igualdad, sin índice compuesto) y de ahí en más la
      // búsqueda por nombre/EAN se filtra en el navegador — no hace falta
      // volver a pedirle nada a Firestore mientras se escribe.
      document.getElementById('cn_selectProveedorActivo').addEventListener('change', async (e) => {
        proveedorActivo = e.target.value;
        const contador = document.getElementById('cn_contadorProveedorActivo');
        document.getElementById('cn_btnLeerRemito').disabled = !proveedorActivo;
        document.getElementById('cn_hintLeerRemito').style.display = proveedorActivo ? 'none' : 'block';
        if (!proveedorActivo) {
          productosDelProveedorActivo = null;
          indiceProductosProveedor = null;
          contador.textContent = '';
          return;
        }
        contador.textContent = 'Cargando productos de ese proveedor...';
        try {
          const q = query(collection(db, 'productos'), where('proveedor', '==', proveedorActivo));
          const snap = await getDocs(q);
          productosDelProveedorActivo = [];
          snap.forEach(d => productosDelProveedorActivo.push({ codigo: d.id, producto: d.data().producto || '' }));
          indiceProductosProveedor = construirIndiceTokens_(productosDelProveedorActivo);
          await cargarAliasesProveedor_(proveedorActivo);
          contador.textContent = `${productosDelProveedorActivo.length} producto(s) de este proveedor — buscá por nombre o código acá arriba`;
        } catch (err) {
          contador.textContent = 'Error cargando productos: ' + err.message;
          productosDelProveedorActivo = null;
        }
      });

      // ---------------- LEER FOTO DE REMITO (Google Cloud Vision) ----------------
      // Flujo: foto -> OCR (texto crudo) -> se intenta separar cada línea en
      // "cantidad" + "descripción" -> se matchea la descripción contra los
      // productos del proveedor elegido -> se muestra una lista editable
      // ANTES de tocar Firestore. Nada impacta en stock hasta tocar "Aceptar".
      let filasRemitoActual = [];

      document.getElementById('cn_btnLeerRemito').addEventListener('click', () => {
        document.getElementById('cn_inputFotoRemito').click();
      });

      document.getElementById('cn_inputFotoRemito').addEventListener('change', (e) => {
        const file = e.target.files[0];
        e.target.value = ''; // permite volver a elegir la misma foto después
        if (file) leerRemitoDesdeFoto(file);
      });

      function leerArchivoComoBase64_(file) {
        return new Promise((resolve, reject) => {
          const reader = new FileReader();
          reader.onload = () => resolve(reader.result.split(',')[1]);
          reader.onerror = reject;
          reader.readAsDataURL(file);
        });
      }

      // Lee el texto de una imagen O un PDF con Google Cloud Vision. Un PDF
      // usa un endpoint distinto (files:annotate, por página) que una imagen
      // (images:annotate) — esta función elige el correcto según el tipo de
      // archivo y devuelve siempre un texto plano, para no tener que pensar
      // en la diferencia en el resto del código.
      async function leerTextoDeArchivoConVision_(file) {
        const base64 = await leerArchivoComoBase64_(file);
        const esPdf = file.type === 'application/pdf';

        if (esPdf) {
          const respuesta = await fetch(`https://vision.googleapis.com/v1/files:annotate?key=${VISION_API_KEY}`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
              requests: [{
                inputConfig: { mimeType: 'application/pdf', content: base64 },
                features: [{ type: 'DOCUMENT_TEXT_DETECTION' }]
              }]
            })
          });
          const data = await respuesta.json();
          if (data.error) throw new Error(data.error.message || 'Error de Vision API');
          const resp0 = data.responses && data.responses[0];
          if (resp0 && resp0.error) throw new Error(resp0.error.message || 'Error leyendo el PDF');
          const paginas = (resp0 && resp0.responses) || [];
          return paginas.map(p => (p.fullTextAnnotation ? p.fullTextAnnotation.text : '')).join('\n');
        }

        const respuesta = await fetch(`https://vision.googleapis.com/v1/images:annotate?key=${VISION_API_KEY}`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            requests: [{ image: { content: base64 }, features: [{ type: 'DOCUMENT_TEXT_DETECTION' }] }]
          })
        });
        const data = await respuesta.json();
        if (data.error) throw new Error(data.error.message || 'Error de Vision API');
        const resp0 = data.responses && data.responses[0];
        if (resp0 && resp0.error) throw new Error(resp0.error.message || 'Error leyendo la imagen');
        return (resp0 && resp0.fullTextAnnotation) ? resp0.fullTextAnnotation.text : '';
      }

      async function leerRemitoDesdeFoto(file) {
        if (!proveedorActivo || !productosDelProveedorActivo) {
          mostrarToast('Elegí primero un proveedor arriba', true);
          return;
        }
        if (VISION_API_KEY.indexOf('PEGAR_ACA') === 0) {
          mostrarToast('Falta configurar la clave de Google Cloud Vision en el código', true);
          return;
        }
        const btn = document.getElementById('cn_btnLeerRemito');
        btn.disabled = true;
        btn.textContent = 'Leyendo...';
        try {
          const textoCompleto = await leerTextoDeArchivoConVision_(file);
          if (!textoCompleto) {
            mostrarToast('No se detectó texto en el archivo', true);
            return;
          }
          procesarTextoRemito_(textoCompleto);
        } catch (err) {
          mostrarToast('Error leyendo el archivo: ' + err.message, true);
        } finally {
          btn.disabled = false;
          btn.textContent = '📷 Leer foto o PDF de remito';
        }
      }

      // Saca tildes, pasa a minúsculas y deja solo letras/números/espacios —
      // para poder comparar texto de OCR (que suele venir con ruido) contra
      // los nombres de productos del catálogo sin que un acento de más rompa
      // la comparación.
      function normalizarTexto_(s) {
        return String(s || '')
          .toLowerCase()
          .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
          .replace(/[^a-z0-9\s]/g, ' ')
          .replace(/\s+/g, ' ')
          .trim();
      }

      // Busca "número + palabra de unidad" (ej: "2 Caja", "5 Unid", "10 Kg") —
      // mucho más confiable que agarrar cualquier número suelto, porque una
      // factura real tiene VARIOS números por línea (código, cantidad,
      // precio, importe) y los precios/importes vienen con coma decimal
      // (ej: "25.180,18") que un match ingenuo confunde con la cantidad.
      // Si el patrón aparece más de una vez en la línea (por ejemplo, la
      // descripción dice "X8 UNID" como parte del nombre del producto), se
      // usa la ÚLTIMA aparición — en un formato de factura normal, la
      // columna Cantidad real siempre es la última, justo antes del Precio.
      const REGEX_CANTIDAD_UNIDAD = /(\d{1,5})\s*(cajas?|cja|unid(?:ad(?:es)?)?|bultos?|kgs?|kilos?|paquetes?|pqt|docenas?|bolsas?|un)\b/gi;

      function extraerCantidadDeLinea_(linea) {
        const matches = [...linea.matchAll(REGEX_CANTIDAD_UNIDAD)];
        if (matches.length) {
          const m = matches[matches.length - 1];
          return { cantidad: parseInt(m[1], 10), unidad: m[2], resto: linea.slice(0, m.index).trim() };
        }
        // Fallback para remitos más simples, sin columna de unidad explícita
        const matchFin = linea.match(/\b(\d{1,4})$/);
        if (matchFin) return { cantidad: parseInt(matchFin[1], 10), unidad: null, resto: linea.slice(0, matchFin.index).trim() };
        const matchInicio = linea.match(/^(\d{1,4})\b/);
        if (matchInicio) return { cantidad: parseInt(matchInicio[1], 10), unidad: null, resto: linea.slice(matchInicio[0].length).trim() };
        return { cantidad: null, unidad: null, resto: linea };
      }

      // "Unidad" o "un" es 1 a 1; cualquier otra cosa (Caja, Bulto, Kg,
      // Paquete, Docena...) significa que el número no son unidades sueltas.
      function unidadRequiereRevision_(unidad) {
        return !!unidad && !/^unid(?:ad(?:es)?)?$|^un$/i.test(unidad);
      }

      // Sanitiza para usar como ID de documento de Firestore (nada de "/", límite de largo)
      function sanitizarIdCliente_(clave) {
        return String(clave).replace(/\//g, '_').substring(0, 300);
      }

      // Trae lo que ya se corrigió antes para este proveedor (aprendizaje
      // simple: cada vez que confirmás una línea, se guarda "este texto de
      // remito = este producto" — así la próxima vez que aparezca un texto
      // parecido, ya no hace falta corregirlo a mano).
      async function cargarAliasesProveedor_(proveedor) {
        aliasesProveedorActivo = {};
        try {
          const q = query(collection(db, 'aliasRemito'), where('proveedor', '==', proveedor));
          const snap = await getDocs(q);
          snap.forEach(d => {
            const data = d.data();
            aliasesProveedorActivo[data.textoNormalizado] = { codigo: data.codigo, producto: data.producto };
          });
        } catch (err) {
          console.error('Error cargando alias de remito', err);
        }
      }

      async function guardarAliasRemito_(proveedor, textoNormalizado, codigo, producto) {
        if (!proveedor || !textoNormalizado || !codigo) return;
        try {
          const id = sanitizarIdCliente_(proveedor + '|' + textoNormalizado);
          await setDoc(doc(db, 'aliasRemito', id), {
            proveedor, textoNormalizado, codigo, producto, actualizado: serverTimestamp()
          }, { merge: true });
          aliasesProveedorActivo[textoNormalizado] = { codigo, producto }; // disponible ya mismo, sin esperar otra lectura
        } catch (err) {
          console.error('Error guardando alias de remito', err);
        }
      }

      // Busca primero en lo ya aprendido para este proveedor (exacto, y si
      // no, que el texto de la línea CONTENGA algún alias guardado — por si
      // el OCR agrega o saca algún caracter de más). Si no encuentra nada
      // ahí, recién ahí cae a la heurística genérica por palabras.
      function buscarAlias_(textoNormalizado) {
        if (aliasesProveedorActivo[textoNormalizado]) return aliasesProveedorActivo[textoNormalizado];
        for (const clave in aliasesProveedorActivo) {
          if (clave.length >= 6 && (textoNormalizado.includes(clave) || clave.includes(textoNormalizado))) {
            return aliasesProveedorActivo[clave];
          }
        }
        return null;
      }

      // Arma, una sola vez por proveedor, un índice de qué tan RARA es cada
      // palabra dentro de SU catálogo — no todas las palabras valen lo
      // mismo para reconocer un producto. Si 13 productos de un proveedor
      // dicen "PUDDING ... 100 DUCADOS" y solo se diferencian por el sabor
      // (CHOCOLATE, LIMON, PISTACHO...), matchear por "PUDDING" no dice
      // nada — hay que darle mucho más peso a "CHOCOLATE" o "PISTACHO",
      // que aparecen en 1 o 2 productos nomás. Es la misma idea que usan
      // los buscadores (TF-IDF), aplicada a nombres de productos cortos.
      function construirIndiceTokens_(listaProductos) {
        const productosConTokens = listaProductos.map(p => ({
          codigo: p.codigo,
          producto: p.producto,
          tokens: [...new Set(normalizarTexto_(p.producto).split(' ').filter(t => t.length >= 2))]
        }));
        const frecuencia = {};
        productosConTokens.forEach(p => p.tokens.forEach(t => { frecuencia[t] = (frecuencia[t] || 0) + 1; }));
        return { productosConTokens, frecuencia };
      }

      // Matchea pesando cada palabra por lo rara que es en el catálogo de
      // ESE proveedor (peso = 1 / cuántos productos la usan). Además, si el
      // mejor candidato y el segundo quedan muy parejos, prefiere NO
      // adivinar antes que arriesgarse a elegir el producto equivocado.
      function mejorMatchProducto_(textoLinea, indice) {
        if (!indice || !indice.productosConTokens.length) return null;
        const tokensLinea = new Set(normalizarTexto_(textoLinea).split(' ').filter(t => t.length >= 2));
        if (!tokensLinea.size) return null;

        const candidatos = [];
        indice.productosConTokens.forEach(p => {
          if (!p.tokens.length) return;
          let pesoEncontrado = 0, pesoTotal = 0;
          p.tokens.forEach(t => {
            const peso = 1 / (indice.frecuencia[t] || 1);
            pesoTotal += peso;
            if (tokensLinea.has(t)) pesoEncontrado += peso;
          });
          if (pesoTotal <= 0) return;
          candidatos.push({ codigo: p.codigo, producto: p.producto, score: pesoEncontrado / pesoTotal });
        });

        candidatos.sort((a, b) => b.score - a.score);
        const mejor = candidatos[0];
        if (!mejor || mejor.score < 0.55) return null;

        const segundo = candidatos[1];
        if (segundo && (mejor.score - segundo.score) < 0.15) return null; // muy parejo, mejor no adivinar

        return { codigo: mejor.codigo, producto: mejor.producto };
      }

      function procesarTextoRemito_(texto) {
        const lineas = texto.split('\n').map(l => l.trim()).filter(l => l.length > 2);
        const filas = [];
        lineas.forEach(linea => {
          const { cantidad, unidad, resto } = extraerCantidadDeLinea_(linea);
          if (!cantidad || !resto || resto.length < 3) return; // sin número o sin texto: probablemente encabezado/ruido, se ignora sola

          const textoNormalizado = normalizarTexto_(resto);
          const porAlias = buscarAlias_(textoNormalizado);
          const match = porAlias || mejorMatchProducto_(resto, indiceProductosProveedor);

          filas.push({
            lineaOriginal: linea,
            textoNormalizado: textoNormalizado,
            cantidad: cantidad,
            unidad: unidad,
            revisarUnidad: unidadRequiereRevision_(unidad),
            codigo: match ? match.codigo : '',
            producto: match ? match.producto : '',
            reconocido: !!match,
            porAlias: !!porAlias
          });
        });
        mostrarRevisionRemito_(filas);
      }

      function mostrarRevisionRemito_(filas) {
        filasRemitoActual = filas;
        renderizarRevisionRemito_();
        document.getElementById('cn_modalRevisionRemito').classList.add('show');
      }

      function renderizarRevisionRemito_() {
        const cont = document.getElementById('cn_revisionRemitoContenido');
        const btnAceptar = document.getElementById('cn_btnAceptarRemito');
        if (!filasRemitoActual.length) {
          cont.innerHTML = '<div class="empty-state">No se detectó ninguna línea con cantidad + descripción. Probá con otra foto: más derecha, con buena luz y sin sombras.</div>';
          btnAceptar.style.display = 'none';
          return;
        }
        btnAceptar.style.display = 'block';
        const validas = filasRemitoActual.filter(f => f.codigo && f.cantidad > 0).length;
        btnAceptar.textContent = `✔ Aceptar e ingresar (${validas})`;

        const opciones = productosDelProveedorActivo
          .map(p => `<option value="${escapeAttrJs(p.codigo)}">${escapeHtml(p.producto)}</option>`).join('');

        cont.innerHTML = filasRemitoActual.map((f, idx) => `
          <div style="border:1px solid var(--border); border-radius:10px; padding:10px; margin-bottom:8px; ${f.reconocido ? '' : 'background:#fff7ed; border-color:#fed7aa;'}">
            ${!f.reconocido ? '<div style="color:#ea580c; font-size:11px; font-weight:700; margin-bottom:4px;">⚠ No estoy seguro de cuál es — elegilo a mano</div>' : ''}
            ${f.revisarUnidad ? `<div style="color:#9333ea; font-size:11px; font-weight:700; margin-bottom:4px;">📦 Detecté "${f.cantidad} ${escapeHtml(f.unidad)}" — si no son unidades sueltas, corregí la cantidad real de unidades abajo</div>` : ''}
            ${f.reconocido && f.porAlias ? '<div style="color:#16a34a; font-size:11px; font-weight:700; margin-bottom:4px;">✓ Reconocido de una carga anterior</div>' : ''}
            <select id="cn_selectRemito-${idx}" onchange="window.__cambiarProductoRemito(${idx}, this.value)"
              style="width:100%; padding:8px; border:1px solid var(--border); border-radius:8px; font-size:13px; margin-bottom:6px;">
              <option value="">— Ignorar esta línea —</option>
              ${opciones}
            </select>
            <div style="display:flex; align-items:center; gap:8px;">
              <label style="font-size:12px; color:var(--muted);">Cantidad:</label>
              <input type="number" min="0" value="${f.cantidad}" onchange="window.__cambiarCantidadRemito(${idx}, this.value)"
                style="width:80px; padding:6px; border:1px solid var(--border); border-radius:8px;">
            </div>
            <div style="font-size:11px; color:var(--muted); margin-top:6px; font-style:italic;">Detectado: "${escapeHtml(f.lineaOriginal)}"</div>
          </div>
        `).join('');

        filasRemitoActual.forEach((f, idx) => {
          if (f.codigo) document.getElementById(`cn_selectRemito-${idx}`).value = f.codigo;
        });
      }

      window.__cambiarProductoRemito = function(idx, codigo) {
        const p = productosDelProveedorActivo.find(x => x.codigo === codigo);
        filasRemitoActual[idx].codigo = codigo;
        filasRemitoActual[idx].producto = p ? p.producto : '';
        filasRemitoActual[idx].reconocido = !!codigo;
        const validas = filasRemitoActual.filter(f => f.codigo && f.cantidad > 0).length;
        document.getElementById('cn_btnAceptarRemito').textContent = `✔ Aceptar e ingresar (${validas})`;
      };

      window.__cambiarCantidadRemito = function(idx, valor) {
        filasRemitoActual[idx].cantidad = parseInt(valor, 10) || 0;
        const validas = filasRemitoActual.filter(f => f.codigo && f.cantidad > 0).length;
        document.getElementById('cn_btnAceptarRemito').textContent = `✔ Aceptar e ingresar (${validas})`;
      };

      document.getElementById('cn_btnAceptarRemito').addEventListener('click', async () => {
        const filasValidas = filasRemitoActual.filter(f => f.codigo && f.cantidad > 0);
        if (!filasValidas.length) { mostrarToast('No hay ninguna línea válida para ingresar', true); return; }

        const btn = document.getElementById('cn_btnAceptarRemito');
        btn.disabled = true;
        btn.textContent = 'Ingresando...';

        let ok = 0, conError = 0;
        for (const f of filasValidas) {
          try {
            await ingresarStockDirecto_(f.codigo, f.producto, f.cantidad);
            if (f.textoNormalizado) await guardarAliasRemito_(proveedorActivo, f.textoNormalizado, f.codigo, f.producto);
            ok++;
          } catch (err) {
            conError++;
            console.error('Error ingresando fila de remito', f, err);
          }
        }

        btn.disabled = false;
        document.getElementById('cn_modalRevisionRemito').classList.remove('show');
        mostrarToast(`✔ Ingresados ${ok} producto(s)` + (conError ? ` — ${conError} con error` : ''), conError > 0 && ok === 0);
      });

      // Misma lógica que la transacción de confirmarConteo, pero sin pedir
      // posición: usa la posición principal ya guardada, o "SIN UBICAR" si
      // el producto todavía no tiene ninguna (se puede corregir después con
      // el ✏️ del Armador o recontándolo).
      async function ingresarStockDirecto_(codigo, nombreProducto, cantidadEnUnidades) {
        const resultado = await runTransaction(db, async (tx) => {
          const productoRef = doc(db, 'productos', codigo);
          const productoSnap = await tx.get(productoRef);
          const posicion = (productoSnap.exists() && productoSnap.data().posicionPrincipal) || 'SIN UBICAR';
          const posRef = doc(db, 'productos', codigo, 'posiciones', posicion);
          const posSnap = await tx.get(posRef);
          const cantidadAnterior = posSnap.exists() ? (posSnap.data().cantidad || 0) : 0;
          const nuevaCantidadPosicion = cantidadAnterior + cantidadEnUnidades;

          tx.set(posRef, {
            codigo: codigo, producto: nombreProducto, cantidad: nuevaCantidadPosicion, ultimaActualizacion: serverTimestamp(),
            ultimoMovimientoPor: persona() ? persona().nombre : null,
            ultimoMovimientoPorDocumento: persona() ? persona().documento : null,
            ultimoMovimientoTipo: 'ingreso_remito'
          }, { merge: true });

          if (productoSnap.exists()) {
            const datosActuales = productoSnap.data();
            const actualizacion = {
              producto: nombreProducto, productoLower: nombreProducto.toLowerCase(),
              stockTotal: increment(cantidadEnUnidades), ultimaActualizacion: serverTimestamp()
            };
            if (!datosActuales.posicionPrincipal) actualizacion.posicionPrincipal = posicion;
            tx.update(productoRef, actualizacion);
          } else {
            tx.set(productoRef, {
              producto: nombreProducto, productoLower: nombreProducto.toLowerCase(),
              stockMinimo: null, codigoInterno: null, stockTotal: cantidadEnUnidades,
              posicionPrincipal: posicion, ultimaActualizacion: serverTimestamp()
            });
          }
          return { posicion, cantidadTotal: nuevaCantidadPosicion };
        });

        agregarASesion(codigo, nombreProducto, resultado.posicion, cantidadEnUnidades, resultado.cantidadTotal, 'Remito (foto)');
      }

      // ---------------- ESCANEO ----------------
      document.getElementById('cn_btnEscanear').addEventListener('click', iniciarEscaneo);
      document.getElementById('cn_btnCancelarScan').addEventListener('click', detenerEscaneo);

      function iniciarEscaneo() {
        document.getElementById('cn_reader').style.display = 'block';
        document.getElementById('cn_btnCancelarScan').style.display = 'block';
        document.getElementById('cn_btnEscanear').style.display = 'none';
        productoBox.classList.remove('show');

        html5QrCode = new Html5Qrcode("cn_reader");
        const config = {
          fps: 10,
          qrbox: { width: 260, height: 140 },
          formatsToSupport: [
            Html5QrcodeSupportedFormats.EAN_13, Html5QrcodeSupportedFormats.EAN_8,
            Html5QrcodeSupportedFormats.UPC_A, Html5QrcodeSupportedFormats.UPC_E,
            Html5QrcodeSupportedFormats.CODE_128, Html5QrcodeSupportedFormats.CODE_39,
            Html5QrcodeSupportedFormats.QR_CODE
          ]
        };
        html5QrCode.start({ facingMode: "environment" }, config, onScanSuccess)
          .catch(() => { mostrarToast("No se pudo abrir la cámara", true); detenerEscaneo(); });
      }

      function detenerEscaneo() {
        if (document.activeElement) document.activeElement.blur();
        if (html5QrCode) {
          html5QrCode.stop().then(() => { html5QrCode.clear(); html5QrCode = null; }).catch(() => {});
        }
        document.getElementById('cn_reader').style.display = 'none';
        document.getElementById('cn_btnCancelarScan').style.display = 'none';
        document.getElementById('cn_btnEscanear').style.display = 'block';
      }

      function onScanSuccess(codigo) {
        detenerEscaneo();
        if (navigator.vibrate) navigator.vibrate(80);
        buscarProducto(codigo);
      }

      document.getElementById('cn_btnBuscarManual').addEventListener('click', () => {
        const codigo = document.getElementById('cn_inputCodigoManual').value.trim();
        if (!codigo) { mostrarToast("Ingresá un código", true); return; }
        ocultarSugerencias();
        buscarProducto(codigo);
        document.getElementById('cn_inputCodigoManual').value = '';
      });
      document.getElementById('cn_inputCodigoManual').addEventListener('keydown', e => {
        if (e.key === 'Enter') document.getElementById('cn_btnBuscarManual').click();
      });

      // ---------------- BÚSQUEDA POR NOMBRE (prefijo, Firestore) ----------------
      let timeoutBusqueda = null;
      document.getElementById('cn_inputCodigoManual').addEventListener('input', () => {
        const texto = document.getElementById('cn_inputCodigoManual').value.trim();
        clearTimeout(timeoutBusqueda);
        if (texto.length < 2) { ocultarSugerencias(); return; }
        timeoutBusqueda = setTimeout(() => buscarSugerencias(texto), 250);
      });

      async function buscarSugerencias(texto) {
        const textoLower = texto.toLowerCase();

        // Con un proveedor elegido, se busca en memoria (contiene, no solo
        // prefijo) sobre lo que ya se trajo al elegirlo — permite matchear
        // tanto por parte del nombre como por el EAN.
        if (productosDelProveedorActivo) {
          const resultados = productosDelProveedorActivo
            .filter(p => p.producto.toLowerCase().includes(textoLower) || p.codigo.includes(texto))
            .slice(0, 10);
          renderizarSugerencias(resultados);
          return;
        }

        try {
          const q = query(
            collection(db, 'productos'),
            orderBy('productoLower'),
            where('productoLower', '>=', textoLower),
            where('productoLower', '<=', textoLower + '\uf8ff'),
            limit(10)
          );
          const snap = await getDocs(q);
          const resultados = [];
          snap.forEach(d => resultados.push({ codigo: d.id, producto: d.data().producto }));
          renderizarSugerencias(resultados);
        } catch (err) {
          console.error('Error buscando sugerencias', err);
        }
      }

      function renderizarSugerencias(resultados) {
        const cont = document.getElementById('cn_sugerenciasManual');
        if (!resultados.length) { ocultarSugerencias(); return; }
        cont.innerHTML = resultados.map(p => `
          <div class="sugerencia-item" onmousedown="window.__seleccionarSugerencia('${p.codigo.replace(/'/g, "\\'")}')">
            <div class="sug-nombre">${escapeHtml(p.producto)}</div>
            <div class="sug-codigo">${escapeHtml(p.codigo)}</div>
          </div>
        `).join('');
        cont.style.display = 'block';
      }

      function ocultarSugerencias() {
        document.getElementById('cn_sugerenciasManual').style.display = 'none';
      }

      window.__seleccionarSugerencia = function(codigo) {
        ocultarSugerencias();
        document.getElementById('cn_inputCodigoManual').value = '';
        buscarProducto(codigo);
      };

      document.addEventListener('click', e => {
        if (!e.target.closest('#inputCodigoManual') && !e.target.closest('#sugerenciasManual')) ocultarSugerencias();
      });

      // ---------------- BUSCAR PRODUCTO (unidad o bulto) ----------------
      async function buscarProducto(codigoInput) {
        const codigo = String(codigoInput).trim();
        try {
          const ref = doc(db, 'productos', codigo);
          const snap = await getDoc(ref);

          if (snap.exists()) {
            const data = snap.data();
            const stock = await obtenerStockDeProducto(codigo);
            mostrarProducto({
              encontrado: true, esBulto: false, codigo: codigo,
              producto: data.producto, stock: stock, posicionPrincipal: data.posicionPrincipal || null
            });
            return;
          }

          // No es un código de unidad conocido: ¿es un bulto?
          const bultoRef = doc(db, 'bultos', codigo);
          const bultoSnap = await getDoc(bultoRef);
          if (bultoSnap.exists()) {
            const b = bultoSnap.data();
            const baseSnap = await getDoc(doc(db, 'productos', b.codigoBase));
            const productoNombre = baseSnap.exists() ? baseSnap.data().producto : b.producto;
            const posicionPrincipalBase = baseSnap.exists() ? (baseSnap.data().posicionPrincipal || null) : null;
            const stock = await obtenerStockDeProducto(b.codigoBase);
            mostrarProducto({
              encontrado: true, esBulto: true, codigo: b.codigoBase,
              codigoBultoEscaneado: codigo, producto: productoNombre,
              unidadesPorBulto: b.unidadesPorBulto, stock: stock, posicionPrincipal: posicionPrincipalBase
            });
            return;
          }

          // No es ni unidad ni bulto: producto no encontrado
          mostrarProducto({ encontrado: false, esBulto: false, codigo: codigo, producto: null, stock: { total: 0, posiciones: [] } });
        } catch (err) {
          mostrarToast("Error buscando producto: " + err.message, true);
        }
      }

      async function obtenerStockDeProducto(codigo) {
        const posSnap = await getDocs(collection(db, 'productos', codigo, 'posiciones'));
        const posiciones = [];
        let total = 0;
        posSnap.forEach(d => {
          const cantidad = d.data().cantidad || 0;
          posiciones.push({ posicion: d.id, cantidad });
          total += cantidad;
        });
        return { total, posiciones };
      }

      // ---------------- MOSTRAR PRODUCTO ----------------
      function mostrarProducto(resultado) {
        productoActual = resultado;
        esBultoActual = !!resultado.esBulto;
        unidadesPorBultoActual = resultado.unidadesPorBulto || 1;

        document.getElementById('cn_pCodigo').textContent = resultado.codigo;

        if (resultado.encontrado) {
          document.getElementById('cn_pNombre').textContent = resultado.producto;
          document.getElementById('cn_pNombre').classList.remove('no-encontrado');
          document.getElementById('cn_nombreManualField').style.display = 'none';
        } else {
          document.getElementById('cn_pNombre').textContent = '⚠ No encontrado en el catálogo';
          document.getElementById('cn_pNombre').classList.add('no-encontrado');
          document.getElementById('cn_nombreManualField').style.display = 'block';
          document.getElementById('cn_inputNombreManual').value = '';
        }

        if (esBultoActual) {
          document.getElementById('cn_pBultoBadge').style.display = 'block';
          document.getElementById('cn_pUnidadesPorBulto').textContent = unidadesPorBultoActual;
          document.getElementById('cn_labelCantidad').textContent = 'Cantidad de bultos/cajas';
          document.getElementById('cn_btnAsociarBulto').style.display = 'none';
        } else {
          document.getElementById('cn_pBultoBadge').style.display = 'none';
          document.getElementById('cn_labelCantidad').textContent = 'Cantidad';
          document.getElementById('cn_btnAsociarBulto').style.display = resultado.encontrado ? 'block' : 'none';
        }
        document.getElementById('cn_btnEliminarProducto').style.display = (resultado.encontrado && esGestion()) ? 'block' : 'none';

        const hintProveedor = document.getElementById('cn_hintPosicionProveedor');
        if (modoProveedor && resultado.posicionPrincipal) {
          document.getElementById('cn_inputPosicion').value = resultado.posicionPrincipal;
          hintProveedor.style.display = 'block';
        } else {
          document.getElementById('cn_inputPosicion').value = ultimaPosicion;
          hintProveedor.style.display = 'none';
        }
        document.getElementById('cn_inputCantidad').value = 1;
        actualizarEquivalenciaBulto();
        renderStockActual(resultado.stock);

        posicionesDisponibles = (resultado.stock && resultado.stock.posiciones) || [];
        document.getElementById('cn_btnModoMover').style.display = posicionesDisponibles.length > 0 ? 'block' : 'none';
        document.getElementById('cn_moverPosicionBox').style.display = 'none';

        productoBox.classList.add('show');
      }

      function actualizarEquivalenciaBulto() {
        const div = document.getElementById('cn_equivalenciaBulto');
        if (!esBultoActual) { div.style.display = 'none'; return; }
        const cantidad = parseInt(document.getElementById('cn_inputCantidad').value, 10) || 0;
        div.style.display = 'block';
        div.textContent = `= ${cantidad * unidadesPorBultoActual} unidades en total`;
      }

      function renderStockActual(stock) {
        const cont = document.getElementById('cn_pStockActual');
        if (!stock || !stock.total) {
          cont.innerHTML = '<span class="stock-badge sin-stock">Sin conteo previo</span>';
          return;
        }
        let html = `<span class="stock-badge">Ya contado: ${stock.total}</span>`;
        if (stock.posiciones.length > 1) {
          const detalle = stock.posiciones.map(p => `${escapeHtml(p.posicion)}: ${p.cantidad}`).join(' · ');
          html += `<div class="stock-detalle">${detalle}</div>`;
        } else if (stock.posiciones.length === 1) {
          html += `<div class="stock-detalle">en ${escapeHtml(stock.posiciones[0].posicion)}</div>`;
        }
        cont.innerHTML = html;
      }

      // ---------------- CANTIDAD ----------------
      document.getElementById('cn_btnMas').addEventListener('click', () => cambiarCantidad(1));
      document.getElementById('cn_btnMenos').addEventListener('click', () => cambiarCantidad(-1));
      document.getElementById('cn_inputCantidad').addEventListener('input', actualizarEquivalenciaBulto);

      function cambiarCantidad(delta) {
        const input = document.getElementById('cn_inputCantidad');
        let val = parseInt(input.value || "1", 10) + delta;
        if (val < 1) val = 1;
        input.value = val;
        actualizarEquivalenciaBulto();
      }

      // ---------------- CONFIRMAR CONTEO (transacción atómica) ----------------
      document.getElementById('cn_btnConfirmar').addEventListener('click', confirmarConteo);
      document.getElementById('cn_btnDescartar').addEventListener('click', descartarProducto);

      async function confirmarConteo() {
        const posicion = document.getElementById('cn_inputPosicion').value.trim();
        const cantidadIngresada = parseInt(document.getElementById('cn_inputCantidad').value, 10);

        if (!posicion) { mostrarToast("Ingresá una posición", true); return; }
        if (!cantidadIngresada || cantidadIngresada <= 0) {
          mostrarToast(esBultoActual ? "Cantidad de bultos inválida" : "Cantidad inválida", true);
          return;
        }

        const cantidadEnUnidades = esBultoActual ? cantidadIngresada * unidadesPorBultoActual : cantidadIngresada;

        let nombreProducto = productoActual.producto;
        if (!productoActual.encontrado) {
          nombreProducto = document.getElementById('cn_inputNombreManual').value.trim();
          if (!nombreProducto) { mostrarToast("Ingresá el nombre del producto", true); return; }
        }

        const btn = document.getElementById('cn_btnConfirmar');
        btn.disabled = true;
        btn.textContent = 'Guardando...';
        ultimaPosicion = posicion;

        const codigo = productoActual.codigo;

        try {
          const cantidadTotal = await runTransaction(db, async (tx) => {
            const productoRef = doc(db, 'productos', codigo);
            const posRef = doc(db, 'productos', codigo, 'posiciones', posicion);

            const productoSnap = await tx.get(productoRef);
            const posSnap = await tx.get(posRef);

            const cantidadAnterior = posSnap.exists() ? (posSnap.data().cantidad || 0) : 0;
            const nuevaCantidadPosicion = cantidadAnterior + cantidadEnUnidades;

            tx.set(posRef, {
              codigo: codigo,
              producto: nombreProducto,
              cantidad: nuevaCantidadPosicion,
              ultimaActualizacion: serverTimestamp(),
              ultimoMovimientoPor: persona() ? persona().nombre : null,
              ultimoMovimientoPorDocumento: persona() ? persona().documento : null,
              ultimoMovimientoTipo: modoProveedor ? 'ingreso_proveedor' : 'conteo'
            }, { merge: true });

            if (productoSnap.exists()) {
              const datosActuales = productoSnap.data();
              const actualizacion = {
                producto: nombreProducto,
                productoLower: nombreProducto.toLowerCase(),
                stockTotal: increment(cantidadEnUnidades),
                ultimaActualizacion: serverTimestamp()
              };
              // Si el producto ya existía en Firestore (por ejemplo, porque
              // se creó desde el catálogo antes de contarlo nunca) pero
              // todavía no tenía posición principal, esta primera cuenta
              // real se la completa. Antes esta rama nunca la tocaba, y
              // quedaba "Sin posición" en el Armador aunque el stock ya
              // estuviera cargado.
              if (!datosActuales.posicionPrincipal) {
                actualizacion.posicionPrincipal = posicion;
              }
              tx.update(productoRef, actualizacion);
            } else {
              tx.set(productoRef, {
                producto: nombreProducto,
                productoLower: nombreProducto.toLowerCase(),
                stockMinimo: null,
                codigoInterno: null,
                stockTotal: cantidadEnUnidades,
                posicionPrincipal: posicion,
                ultimaActualizacion: serverTimestamp()
              });
            }

            return nuevaCantidadPosicion;
          });

          const detalleSesion = esBultoActual ? `${cantidadIngresada} bulto(s) x${unidadesPorBultoActual}` : null;
          agregarASesion(codigo, nombreProducto, posicion, cantidadEnUnidades, cantidadTotal, detalleSesion);
          mostrarToast("Guardado ✓");
          productoBox.classList.remove('show');
        } catch (err) {
          mostrarToast("Error guardando: " + err.message, true);
        } finally {
          btn.disabled = false;
          btn.textContent = '✔ Confirmar y guardar';
        }
      }

      function descartarProducto() {
        productoBox.classList.remove('show');
        productoActual = null;
      }

      // ---------------- ELIMINAR PRODUCTO (restringido por DNI) ----------------
      // Borra el producto entero de Firestore (documento + todas sus
      // posiciones) — para sacar de encima algo que se cargó mal (código
      // escaneado mal, duplicado, etc.). Solo dos DNIs autorizados.
      document.getElementById('cn_btnEliminarProducto').addEventListener('click', eliminarProductoActual);

      async function eliminarProductoActual() {
        if (!productoActual || !productoActual.codigo) return;

        if (!esGestion()) { mostrarToast('No autorizado para eliminar productos', true); return; }

        const codigo = productoActual.codigo;
        const nombreMostrado = productoActual.producto || document.getElementById('cn_inputNombreManual').value.trim() || codigo;
        if (!confirm(`¿Seguro que querés eliminar "${nombreMostrado}" (${codigo})?\n\nSe borra TODO su stock y no se puede deshacer.`)) return;

        const btn = document.getElementById('cn_btnEliminarProducto');
        btn.disabled = true;
        btn.textContent = 'Eliminando...';
        try {
          const posSnap = await getDocs(collection(db, 'productos', codigo, 'posiciones'));
          for (const d of posSnap.docs) {
            await deleteDoc(d.ref);
          }
          await deleteDoc(doc(db, 'productos', codigo));
          mostrarToast('Producto eliminado ✓');
          descartarProducto();
        } catch (err) {
          mostrarToast('Error eliminando: ' + err.message, true);
        } finally {
          btn.disabled = false;
          btn.textContent = '🗑 Eliminar este producto (borra todo su stock)';
        }
      }

      function agregarASesion(codigo, nombre, posicion, cantidad, totalAcumulado, detalleBulto) {
        sesion.unshift({ codigo, nombre, posicion, cantidad, totalAcumulado, detalleBulto });
        renderSesion();
      }

      function renderSesion() {
        const cont = document.getElementById('cn_listaSesion');
        document.getElementById('cn_totalSesion').textContent = sesion.length + " producto" + (sesion.length === 1 ? "" : "s");
        if (sesion.length === 0) {
          cont.innerHTML = '<div class="empty-state">Todavía no escaneaste nada</div>';
          return;
        }
        cont.innerHTML = sesion.map(item => `
          <div class="session-item">
            <div>
              <div class="nombre">${escapeHtml(item.nombre)}</div>
              <div class="detalle">${escapeHtml(item.codigo)} · Pos. ${escapeHtml(item.posicion)}${item.detalleBulto ? ' · 📦 ' + escapeHtml(item.detalleBulto) : ''}</div>
            </div>
            <div class="cant">+${item.cantidad} <span style="color:var(--muted); font-weight:400;">(total: ${item.totalAcumulado})</span></div>
          </div>
        `).join('');
      }

      // ---------------- MOVER/CORREGIR POSICIÓN EXISTENTE ----------------
      document.getElementById('cn_btnModoMover').addEventListener('click', abrirModoMover);
      document.getElementById('cn_btnCancelarMover').addEventListener('click', () => {
        document.getElementById('cn_moverPosicionBox').style.display = 'none';
      });
      document.getElementById('cn_selectPosicionAMover').addEventListener('change', cargarDatosPosicionSeleccionada);
      document.getElementById('cn_btnGuardarMovimiento').addEventListener('click', guardarMovimientoPosicion);

      function abrirModoMover() {
        const select = document.getElementById('cn_selectPosicionAMover');
        const selectorField = document.getElementById('cn_selectorPosicionField');
        if (posicionesDisponibles.length > 1) {
          selectorField.style.display = 'block';
          select.innerHTML = posicionesDisponibles.map(p =>
            `<option value="${escapeAttrJs(p.posicion)}">${escapeHtml(p.posicion)} (${p.cantidad} u.)</option>`
          ).join('');
        } else {
          selectorField.style.display = 'none';
        }
        document.getElementById('cn_moverPosicionBox').style.display = 'block';
        cargarDatosPosicionSeleccionada();
        document.getElementById('cn_moverPosicionBox').scrollIntoView({ behavior: 'smooth', block: 'center' });
      }

      function cargarDatosPosicionSeleccionada() {
        let posicionElegida = posicionesDisponibles.length > 1
          ? document.getElementById('cn_selectPosicionAMover').value
          : posicionesDisponibles[0].posicion;
        const datos = posicionesDisponibles.find(p => p.posicion === posicionElegida) || posicionesDisponibles[0];
        document.getElementById('cn_inputNuevaPosicion').value = datos.posicion;
        document.getElementById('cn_inputCantidadPosicion').value = datos.cantidad;
      }

      async function guardarMovimientoPosicion() {
        const posicionOriginal = posicionesDisponibles.length > 1
          ? document.getElementById('cn_selectPosicionAMover').value
          : posicionesDisponibles[0].posicion;
        const nuevaPosicion = document.getElementById('cn_inputNuevaPosicion').value.trim();
        const nuevaCantidad = parseInt(document.getElementById('cn_inputCantidadPosicion').value, 10);

        if (!nuevaPosicion) { mostrarToast("La posición no puede estar vacía", true); return; }
        if (isNaN(nuevaCantidad) || nuevaCantidad < 0) { mostrarToast("Cantidad inválida", true); return; }

        const btn = document.getElementById('cn_btnGuardarMovimiento');
        btn.disabled = true;
        btn.textContent = 'Guardando...';
        const codigo = productoActual.codigo;

        try {
          await runTransaction(db, async (tx) => {
            const productoRef = doc(db, 'productos', codigo);
            const origenRef = doc(db, 'productos', codigo, 'posiciones', posicionOriginal);
            const origenSnap = await tx.get(origenRef);
            const cantidadOrigenAnterior = origenSnap.exists() ? (origenSnap.data().cantidad || 0) : 0;

            if (posicionOriginal === nuevaPosicion) {
              const delta = nuevaCantidad - cantidadOrigenAnterior;
              if (nuevaCantidad === 0) {
                tx.delete(origenRef);
              } else {
                tx.set(origenRef, { cantidad: nuevaCantidad, ultimaActualizacion: serverTimestamp() }, { merge: true });
              }
              tx.update(productoRef, { stockTotal: increment(delta), ultimaActualizacion: serverTimestamp() });
              return;
            }

            const destinoRef = doc(db, 'productos', codigo, 'posiciones', nuevaPosicion);
            const destinoSnap = await tx.get(destinoRef);
            const productoSnap = await tx.get(productoRef); // para saber si lo que se mueve es la posición principal
            const cantidadDestinoAnterior = destinoSnap.exists() ? (destinoSnap.data().cantidad || 0) : 0;

            tx.delete(origenRef);
            if (nuevaCantidad > 0) {
              tx.set(destinoRef, {
                codigo: codigo, producto: productoActual.producto,
                cantidad: cantidadDestinoAnterior + nuevaCantidad,
                ultimaActualizacion: serverTimestamp()
              }, { merge: true });
            }

            const deltaTotal = nuevaCantidad - cantidadOrigenAnterior;
            const cambiosProducto = { stockTotal: increment(deltaTotal), ultimaActualizacion: serverTimestamp() };
            if (nuevaCantidad > 0 && productoSnap.exists() && productoSnap.data().posicionPrincipal === posicionOriginal) cambiosProducto.posicionPrincipal = nuevaPosicion;
            tx.update(productoRef, cambiosProducto);
          });

          mostrarToast("Posición actualizada ✓");
          document.getElementById('cn_moverPosicionBox').style.display = 'none';
          productoBox.classList.remove('show');
        } catch (err) {
          mostrarToast("Error: " + err.message, true);
        } finally {
          btn.disabled = false;
          btn.textContent = '✔ Guardar movimiento';
        }
      }

      // ---------------- ASOCIAR BULTO ----------------
      document.getElementById('cn_btnAsociarBulto').addEventListener('click', abrirAsociarBulto);
      document.getElementById('cn_btnCancelarAsociarBulto').addEventListener('click', cerrarAsociarBulto);
      document.getElementById('cn_btnEscanearBulto').addEventListener('click', iniciarEscaneoBulto);
      document.getElementById('cn_btnCancelarScanBulto').addEventListener('click', detenerEscaneoBulto);
      document.getElementById('cn_btnUsarCodigoBultoManual').addEventListener('click', () => {
        const codigo = document.getElementById('cn_inputCodigoBultoManual').value.trim();
        if (!codigo) { mostrarToast("Ingresá un código", true); return; }
        mostrarPaso2Bulto(codigo);
      });
      document.getElementById('cn_btnGuardarBulto').addEventListener('click', guardarBulto);
      document.getElementById('cn_btnGuardarBultoDirecto').addEventListener('click', guardarBultoDirecto);

      // Para cuando el bulto/caja no tiene su propio código de barras para
      // escanear — se guarda directo en el producto ("unidadesPorBulto"),
      // sin pasar por la colección "bultos" (que requiere un código de
      // caja distinto). Lo usan tanto el conteo como "Armar pedido".
      async function guardarBultoDirecto() {
        const unidadesPorBulto = parseInt(document.getElementById('cn_inputUnidadesPorBultoDirecto').value, 10);
        if (!unidadesPorBulto || unidadesPorBulto <= 0) { mostrarToast("Ingresá cuántas unidades trae el bulto", true); return; }

        const btn = document.getElementById('cn_btnGuardarBultoDirecto');
        btn.disabled = true;
        btn.textContent = 'Guardando...';
        try {
          await setDoc(doc(db, 'productos', productoActual.codigo), {
            unidadesPorBulto: unidadesPorBulto
          }, { merge: true });
          mostrarToast("Guardado ✓ (" + unidadesPorBulto + " unidades por bulto)");
          document.getElementById('cn_asociarBultoBox').style.display = 'none';
        } catch (err) {
          mostrarToast("Error: " + err.message, true);
        } finally {
          btn.disabled = false;
          btn.textContent = 'Guardar';
        }
      }

      function abrirAsociarBulto() {
        productoBox.classList.remove('show');
        document.getElementById('cn_abProducto').textContent = productoActual.producto;
        document.getElementById('cn_abPaso1').style.display = 'block';
        document.getElementById('cn_abPaso2').style.display = 'none';
        document.getElementById('cn_inputCodigoBultoManual').value = '';
        document.getElementById('cn_abUnidadesPorBulto').value = '';
        document.getElementById('cn_asociarBultoBox').style.display = 'block';
      }

      function cerrarAsociarBulto() {
        detenerEscaneoBulto();
        document.getElementById('cn_asociarBultoBox').style.display = 'none';
      }

      function iniciarEscaneoBulto() {
        document.getElementById('cn_readerBulto').style.display = 'block';
        document.getElementById('cn_btnCancelarScanBulto').style.display = 'block';
        document.getElementById('cn_btnEscanearBulto').style.display = 'none';

        html5QrCodeBulto = new Html5Qrcode("cn_readerBulto");
        const config = {
          fps: 10, qrbox: { width: 260, height: 140 },
          formatsToSupport: [
            Html5QrcodeSupportedFormats.EAN_13, Html5QrcodeSupportedFormats.EAN_8,
            Html5QrcodeSupportedFormats.UPC_A, Html5QrcodeSupportedFormats.UPC_E,
            Html5QrcodeSupportedFormats.CODE_128, Html5QrcodeSupportedFormats.CODE_39,
            Html5QrcodeSupportedFormats.QR_CODE
          ]
        };
        html5QrCodeBulto.start({ facingMode: "environment" }, config, codigo => {
          detenerEscaneoBulto();
          if (navigator.vibrate) navigator.vibrate(80);
          mostrarPaso2Bulto(codigo);
        }).catch(() => { mostrarToast("No se pudo abrir la cámara", true); detenerEscaneoBulto(); });
      }

      function detenerEscaneoBulto() {
        if (document.activeElement) document.activeElement.blur();
        if (html5QrCodeBulto) {
          html5QrCodeBulto.stop().then(() => { html5QrCodeBulto.clear(); html5QrCodeBulto = null; }).catch(() => {});
        }
        document.getElementById('cn_readerBulto').style.display = 'none';
        document.getElementById('cn_btnCancelarScanBulto').style.display = 'none';
        document.getElementById('cn_btnEscanearBulto').style.display = 'block';
      }

      function mostrarPaso2Bulto(codigoBulto) {
        document.getElementById('cn_abCodigoBulto').value = codigoBulto;
        document.getElementById('cn_abPaso1').style.display = 'none';
        document.getElementById('cn_abPaso2').style.display = 'block';
      }

      async function guardarBulto() {
        const codigoBulto = document.getElementById('cn_abCodigoBulto').value.trim();
        const unidadesPorBulto = parseInt(document.getElementById('cn_abUnidadesPorBulto').value, 10);
        if (!unidadesPorBulto || unidadesPorBulto <= 0) { mostrarToast("Ingresá cuántas unidades trae el bulto", true); return; }
        if (codigoBulto === productoActual.codigo) { mostrarToast("El código de la caja no puede ser igual al de la unidad", true); return; }

        const btn = document.getElementById('cn_btnGuardarBulto');
        btn.disabled = true;
        btn.textContent = 'Guardando...';

        try {
          await setDoc(doc(db, 'bultos', codigoBulto), {
            codigoBase: productoActual.codigo,
            producto: productoActual.producto,
            unidadesPorBulto: unidadesPorBulto,
            fechaActualizacion: serverTimestamp()
          }, { merge: true });
          mostrarToast("Bulto asociado ✓ (" + unidadesPorBulto + " unidades)");
          document.getElementById('cn_asociarBultoBox').style.display = 'none';
        } catch (err) {
          mostrarToast("Error: " + err.message, true);
        } finally {
          btn.disabled = false;
          btn.textContent = '✔ Guardar asociación';
        }
      }

      // ---------------- VER STOCK ----------------

      // ---------------- VISTA COMPRAS: stock por producto, filtrado por proveedor ----------------
      let productosComprasMaestro = null; // se carga una sola vez; null = todavía no cargado

      let listaProveedoresCache = null; // se carga una sola vez, se reutiliza en cualquier selector de proveedor

      async function obtenerListaProveedores_() {
        if (listaProveedoresCache) return listaProveedoresCache;
        const snap = await getDocs(collection(db, 'proveedores'));
        const nombres = [];
        snap.forEach(d => nombres.push(d.data().nombre || d.id));
        nombres.sort((a, b) => a.localeCompare(b, 'es'));
        listaProveedoresCache = nombres;
        return nombres;
      }

      async function poblarSelectProveedores_(selectEl) {
        if (selectEl.dataset.poblado === '1') return; // ya se pobló este select, no duplicar opciones
        try {
          const nombres = await obtenerListaProveedores_();
          nombres.forEach(nombre => {
            const opt = document.createElement('option');
            opt.value = nombre; opt.textContent = nombre;
            selectEl.appendChild(opt);
          });
          selectEl.dataset.poblado = '1';
        } catch (err) {
          console.error('Error cargando proveedores', err);
        }
      }

      async function abrirVistaCompras() {
        document.getElementById('cn_buscarProductoCompras').value = '';

        await poblarSelectProveedores_(document.getElementById('cn_selectProveedorCompras'));
        if (!productosComprasMaestro) await cargarProductosCompras_();
        renderizarVistaCompras_();
      }

      async function cargarProductosCompras_() {
        const cont = document.getElementById('cn_comprasContenido');
        cont.innerHTML = '<div class="cargando">Cargando productos...</div>';
        try {
          const [snapProductos, snapPosiciones] = await Promise.all([
            getDocs(collection(db, 'productos')),
            getDocs(collectionGroup(db, 'posiciones'))
          ]);

          // "¿Tiene alguna posición cargada?" es una señal más confiable que
          // stockTotal para saber si un producto se contó alguna vez — un
          // stockTotal en 0 puede venir de la carga inicial del catálogo
          // (nunca se tocó) o de que se contó y después se consumió todo;
          // sin ninguna posición en la subcolección, seguro nunca se contó.
          const codigosConPosicion = new Set();
          snapPosiciones.forEach(d => {
            const data = d.data();
            if (data.codigo) codigosConPosicion.add(data.codigo);
          });

          productosComprasMaestro = [];
          snapProductos.forEach(d => {
            const data = d.data();
            productosComprasMaestro.push({
              codigo: d.id,
              codigoInterno: data.codigoInterno || '',
              producto: data.producto || '(sin nombre)',
              proveedor: data.proveedor || '',
              stockTotal: data.stockTotal,
              tieneAlgunaPosicion: codigosConPosicion.has(d.id),
              posicionPrincipal: data.posicionPrincipal || '',
              unidadesPorBulto: data.unidadesPorBulto || null
            });
          });
        } catch (err) {
          cont.innerHTML = `<div class="empty-state">Error: ${err.message}</div>`;
          throw err;
        }
      }

      document.getElementById('cn_selectProveedorCompras').addEventListener('change', renderizarVistaCompras_);
      document.getElementById('cn_buscarProductoCompras').addEventListener('input', renderizarVistaCompras_);

      // ---------------- ARMAR PEDIDO A PROVEEDOR ----------------
      // Flujo: elegís proveedor -> pegás ventas (Código + Cantidad, copiado
      // de Excel) -> se calcula cuánto pedir de cada producto (vendido +
      // colchón - stock actual) -> se puede editar cada fila a mano, elegir
      // unidades o cajas si el producto tiene un bulto asociado, y guardar
      // el criterio (colchón) de cada producto+proveedor para la próxima
      // vez -> se descarga un PDF con el pedido final.
      let filasPedidoActual = [];
      let bultosPorCodigoBase = null; // cache: codigoBase -> {codigoBulto, unidadesPorBulto}

      async function abrirArmarPedido() {
        document.getElementById('cn_resultadoPedidoContenido').innerHTML = '';
        document.getElementById('cn_barraPedidoPDF').style.display = 'none';
        await poblarSelectProveedores_(document.getElementById('cn_selectProveedorPedido'));
      }

      async function cargarBultosReverso_() {
        const snap = await getDocs(collection(db, 'bultos'));
        const mapa = {};
        snap.forEach(d => {
          const data = d.data();
          if (data.codigoBase) mapa[data.codigoBase] = { codigoBulto: d.id, unidadesPorBulto: Number(data.unidadesPorBulto) || 1 };
        });
        bultosPorCodigoBase = mapa;
      }

      // El "criterio de compra" (si se calcula directo o con colchón, y
      // cuánto) queda guardado por proveedor+código — cada uno puede tener
      // un comportamiento distinto, así que no hay una fórmula única global.
      async function cargarCriteriosProveedor_(proveedor) {
        const mapa = {};
        try {
          const q = query(collection(db, 'criteriosCompra'), where('proveedor', '==', proveedor));
          const snap = await getDocs(q);
          snap.forEach(d => {
            const data = d.data();
            mapa[data.codigo] = { colchon: Number(data.colchon) || 0 };
          });
        } catch (err) {
          console.error('Error cargando criterios de compra', err);
        }
        return mapa;
      }

      document.getElementById('cn_selectProveedorPedido').addEventListener('change', () => {
        const proveedor = document.getElementById('cn_selectProveedorPedido').value;
        if (!proveedor) {
          filasPedidoActual = [];
          document.getElementById('cn_resultadoPedidoContenido').innerHTML = '';
          document.getElementById('cn_barraPedidoPDF').style.display = 'none';
          return;
        }
        mostrarProductosProveedor_(proveedor);
      });

      document.getElementById('cn_btnCalcularPedido').addEventListener('click', calcularPedido_);

      // Núcleo compartido: arma UNA fila por cada producto del proveedor
      // (no solo los que vinieron en las ventas pegadas) y, si hay ventas,
      // completa "Vendido" y recalcula el sugerido para los que matchean.
      // Así se ve el catálogo completo apenas elegís el proveedor, y pegar
      // las ventas después solo RELLENA esa misma tabla, no la reemplaza.
      async function construirFilasProveedor_(proveedor, ventasPorCodigo) {
        if (!productosComprasMaestro) await cargarProductosCompras_();
        if (!bultosPorCodigoBase) await cargarBultosReverso_();
        const criterios = await cargarCriteriosProveedor_(proveedor);

        const productosDelProveedor = productosComprasMaestro.filter(p => p.proveedor === proveedor);
        const productosPorCodigo = {};
        const productosPorCodigoInterno = {};
        productosDelProveedor.forEach(p => {
          productosPorCodigo[p.codigo] = p;
          if (p.codigoInterno) productosPorCodigoInterno[p.codigoInterno] = p;
        });

        // Para no perder pegados que no matchean con nada de este proveedor
        const codigosUsados = new Set();

        const filas = productosDelProveedor.map(prod => {
          const codigo = prod.codigo;
          // El código pegado puede ser el de barras o el interno — busco
          // por los dos antes de darlo por no vendido.
          let vendido = 0;
          if (Object.prototype.hasOwnProperty.call(ventasPorCodigo, codigo)) {
            vendido = ventasPorCodigo[codigo]; codigosUsados.add(codigo);
          } else if (prod.codigoInterno && Object.prototype.hasOwnProperty.call(ventasPorCodigo, prod.codigoInterno)) {
            vendido = ventasPorCodigo[prod.codigoInterno]; codigosUsados.add(prod.codigoInterno);
          }

          const stock = prod.tieneAlgunaPosicion ? (Number(prod.stockTotal) || 0) : 0;
          const colchon = (criterios[codigo] && criterios[codigo].colchon) || 0;
          const sugerido = Math.max(0, Math.round(vendido + colchon - stock));
          const bulto = bultosPorCodigoBase[codigo] || (prod.unidadesPorBulto ? { unidadesPorBulto: prod.unidadesPorBulto, directo: true } : null);

          return {
            codigo, producto: prod.producto, vendido, stock, colchon,
            cantidadPedir: sugerido, unidad: 'unidades', bulto
          };
        });

        // Códigos pegados que no pertenecen a ningún producto de este proveedor
        const sinMatch = Object.keys(ventasPorCodigo)
          .filter(c => !codigosUsados.has(c))
          .map(c => ({ codigo: c, producto: '(no encontrado en este proveedor)', vendido: ventasPorCodigo[c], sinMatch: true }));

        return filas.concat(sinMatch);
      }

      async function mostrarProductosProveedor_(proveedor) {
        const cont = document.getElementById('cn_resultadoPedidoContenido');
        cont.innerHTML = '<div class="cargando">Cargando productos del proveedor...</div>';
        try {
          filasPedidoActual = await construirFilasProveedor_(proveedor, {});
          renderizarPedido_();
        } catch (err) {
          cont.innerHTML = `<div class="empty-state">Error: ${err.message}</div>`;
        }
      }

      async function calcularPedido_() {
        const proveedor = document.getElementById('cn_selectProveedorPedido').value;
        if (!proveedor) { mostrarToast('Elegí un proveedor primero', true); return; }
        const texto = document.getElementById('cn_textareaVentas').value.trim();
        if (!texto) { mostrarToast('Pegá las ventas primero', true); return; }

        const btn = document.getElementById('cn_btnCalcularPedido');
        btn.disabled = true;
        btn.textContent = 'Calculando...';

        try {
          // Parsear lo pegado: "codigo<TAB>cantidad" por línea (tal cual
          // queda al copiar dos columnas de Excel y pegarlas acá).
          const ventasPorCodigo = {};
          texto.split('\n').forEach(linea => {
            const limpia = linea.trim();
            if (!limpia) return;
            const partes = limpia.split(/\t+/);
            let codigo, cantidad;
            if (partes.length >= 2) {
              codigo = partes[0].trim();
              cantidad = parseFloat(partes[1].replace(',', '.'));
            } else {
              const partesEsp = limpia.split(/\s+/);
              if (partesEsp.length >= 2) {
                codigo = partesEsp[0];
                cantidad = parseFloat(partesEsp[partesEsp.length - 1].replace(',', '.'));
              }
            }
            if (codigo && !isNaN(cantidad)) ventasPorCodigo[codigo] = cantidad;
          });

          if (!Object.keys(ventasPorCodigo).length) {
            mostrarToast('No pude leer ninguna fila — revisá que sea Código y Cantidad, separados por tab', true);
            return;
          }

          filasPedidoActual = await construirFilasProveedor_(proveedor, ventasPorCodigo);
          renderizarPedido_();
        } catch (err) {
          mostrarToast('Error calculando: ' + err.message, true);
        } finally {
          btn.disabled = false;
          btn.textContent = 'Calcular pedido';
        }
      }

      function renderizarPedido_() {
        const cont = document.getElementById('cn_resultadoPedidoContenido');
        if (!filasPedidoActual.length) { cont.innerHTML = '<div class="empty-state">Sin filas</div>'; document.getElementById('cn_barraPedidoPDF').style.display = 'none'; return; }

        // Los que ya tienen venta cargada (completos) van arriba de todo;
        // los sin match del proveedor, al final. Sort estable: dentro de
        // cada grupo mantienen el orden que ya traían.
        filasPedidoActual.sort((a, b) => {
          const rangoA = a.sinMatch ? 2 : (a.vendido > 0 ? 0 : 1);
          const rangoB = b.sinMatch ? 2 : (b.vendido > 0 ? 0 : 1);
          return rangoA - rangoB;
        });

        let html = '<table style="width:100%; border-collapse:collapse; font-size:13px;">';
        html += '<tr><th style="text-align:left; padding:6px 4px;">Código</th><th style="text-align:left; padding:6px 4px;">Producto</th><th style="text-align:left; padding:6px 4px;">Stock</th><th style="text-align:left; padding:6px 4px;">Vendido</th><th style="text-align:left; padding:6px 4px;">Stock de seguridad</th><th style="text-align:left; padding:6px 4px;">A pedir</th><th style="text-align:left; padding:6px 4px;">Unidad</th><th></th></tr>';

        filasPedidoActual.forEach((f, idx) => {
          if (f.sinMatch) {
            html += `<tr style="background:#fef2f2;"><td style="padding:6px 4px;">${escapeHtml(f.codigo)}</td><td colspan="7" style="padding:6px 4px; color:#dc2626;">No encontrado en este proveedor (vendido: ${f.vendido}) — revisá el código</td></tr>`;
            return;
          }
          const opcionesUnidad = f.bulto
            ? `<select data-idx="${idx}" class="select-unidad-pedido" style="padding:6px; border:1px solid var(--border); border-radius:6px;">
                 <option value="unidades" ${f.unidad === 'unidades' ? 'selected' : ''}>Unidades</option>
                 <option value="bultos" ${f.unidad === 'bultos' ? 'selected' : ''}>Cajas (x${f.bulto.unidadesPorBulto})</option>
               </select>`
            : '<span style="color:var(--muted); font-size:11px;">unidades</span>';
          html += `<tr>
            <td style="padding:6px 4px;">${escapeHtml(f.codigo)}</td>
            <td style="padding:6px 4px;">${escapeHtml(f.producto)}</td>
            <td style="padding:6px 4px;">${f.stock}</td>
            <td style="padding:6px 4px;">${f.vendido}</td>
            <td style="padding:6px 4px;"><input type="number" class="input-colchon-pedido" data-idx="${idx}" value="${f.colchon}" style="width:60px; padding:6px; border:1px solid var(--border); border-radius:6px;"></td>
            <td style="padding:6px 4px;"><input type="number" class="input-cantidad-pedido" data-idx="${idx}" value="${f.cantidadPedir}" style="width:70px; padding:6px; border:1px solid var(--border); border-radius:6px; font-weight:700;"></td>
            <td style="padding:6px 4px;">${opcionesUnidad}</td>
            <td style="padding:6px 4px;"><button class="btn-guardar-criterio" data-idx="${idx}" title="Guardar este criterio para la próxima vez" style="background:none; border:none; font-size:15px; cursor:pointer;">💾</button></td>
          </tr>`;
        });
        html += '</table>';
        cont.innerHTML = html;
        document.getElementById('cn_barraPedidoPDF').style.display = 'flex';
      }

      document.getElementById('cn_resultadoPedidoContenido').addEventListener('input', (e) => {
        const idx = e.target.dataset.idx;
        if (idx === undefined) return;
        const fila = filasPedidoActual[idx];
        if (e.target.classList.contains('input-colchon-pedido')) {
          fila.colchon = parseFloat(e.target.value) || 0;
          fila.cantidadPedir = Math.max(0, Math.round(fila.vendido + fila.colchon - fila.stock));
          const inputCantidad = document.querySelector(`.input-cantidad-pedido[data-idx="${idx}"]`);
          if (inputCantidad) inputCantidad.value = fila.cantidadPedir;
        } else if (e.target.classList.contains('input-cantidad-pedido')) {
          fila.cantidadPedir = parseFloat(e.target.value) || 0;
        }
      });

      document.getElementById('cn_resultadoPedidoContenido').addEventListener('change', (e) => {
        const idx = e.target.dataset.idx;
        if (idx === undefined) return;
        if (e.target.classList.contains('select-unidad-pedido')) {
          filasPedidoActual[idx].unidad = e.target.value;
        }
      });

      document.getElementById('cn_resultadoPedidoContenido').addEventListener('click', async (e) => {
        const btnGuardar = e.target.closest('.btn-guardar-criterio');
        if (!btnGuardar) return;
        const idx = btnGuardar.dataset.idx;
        const fila = filasPedidoActual[idx];
        const proveedor = document.getElementById('cn_selectProveedorPedido').value;
        try {
          const id = `${proveedor}|${fila.codigo}`.replace(/\//g, '_').substring(0, 300);
          await setDoc(doc(db, 'criteriosCompra', id), {
            proveedor, codigo: fila.codigo, colchon: fila.colchon,
            actualizado: serverTimestamp()
          });
          mostrarToast('Criterio guardado para ' + fila.producto);
        } catch (err) {
          mostrarToast('Error guardando criterio: ' + err.message, true);
        }
      });

      document.getElementById('cn_btnDescargarPedidoPDF').addEventListener('click', generarPedidoPDF_);

      async function generarPedidoPDF_() {
        const proveedor = document.getElementById('cn_selectProveedorPedido').value;
        const filasValidas = filasPedidoActual.filter(f => !f.sinMatch && f.cantidadPedir > 0);
        if (!filasValidas.length) { mostrarToast('No hay ninguna cantidad a pedir mayor a 0', true); return; }

        const btn = document.getElementById('cn_btnDescargarPedidoPDF');
        btn.disabled = true;
        btn.textContent = 'Generando...';
        try {
          const { jsPDF } = await import('https://cdn.jsdelivr.net/npm/jspdf@2.5.1/+esm');

          const pdf = new jsPDF();
          const ahora = new Date();
          const numeroOC = `OC-${ahora.getFullYear()}${String(ahora.getMonth() + 1).padStart(2, '0')}${String(ahora.getDate()).padStart(2, '0')}-${String(ahora.getHours()).padStart(2, '0')}${String(ahora.getMinutes()).padStart(2, '0')}`;
          const anchoPagina = pdf.internal.pageSize.getWidth();
          const altoPagina = pdf.internal.pageSize.getHeight();
          const MARGEN = 14;
          const ANCHO_UTIL = anchoPagina - MARGEN * 2;

          // Columnas de la tabla: [x, ancho]
          const COL_CODIGO = { x: MARGEN, w: 34 };
          const COL_DESCRIPCION = { x: MARGEN + 34, w: ANCHO_UTIL - 34 - 26 - 32 };
          const COL_CANTIDAD = { x: MARGEN + 34 + (ANCHO_UTIL - 34 - 26 - 32), w: 26 };
          const COL_UNIDAD = { x: MARGEN + ANCHO_UTIL - 32, w: 32 };

          function dibujarEncabezadoTabla_(y) {
            pdf.setFillColor(...COLOR_MARCA_VERDE);
            pdf.rect(MARGEN, y, ANCHO_UTIL, 8, 'F');
            pdf.setTextColor(255, 255, 255);
            pdf.setFont(undefined, 'bold');
            pdf.setFontSize(9);
            pdf.text('Código', COL_CODIGO.x + 2, y + 5.5);
            pdf.text('Descripción', COL_DESCRIPCION.x + 2, y + 5.5);
            pdf.text('Cantidad', COL_CANTIDAD.x + COL_CANTIDAD.w / 2, y + 5.5, { align: 'center' });
            pdf.text('Unidad', COL_UNIDAD.x + COL_UNIDAD.w / 2, y + 5.5, { align: 'center' });
            return y + 8;
          }

          function encabezadoPagina_() {
            try { pdf.addImage(LOGO_BASE64, 'PNG', MARGEN, 10, 32, 21); } catch (e) { /* si el logo falla, seguimos sin él */ }
            pdf.setFontSize(18);
            pdf.setFont(undefined, 'bold');
            pdf.setTextColor(...COLOR_MARCA_VERDE);
            pdf.text('ORDEN DE COMPRA', anchoPagina - MARGEN, 18, { align: 'right' });
            pdf.setFontSize(10);
            pdf.setFont(undefined, 'normal');
            pdf.setTextColor(80, 80, 80);
            pdf.text(`N°: ${numeroOC}`, anchoPagina - MARGEN, 25, { align: 'right' });
            pdf.text(`Fecha: ${ahora.toLocaleDateString('es-AR')} ${ahora.toLocaleTimeString('es-AR', { hour: '2-digit', minute: '2-digit' })}`, anchoPagina - MARGEN, 30, { align: 'right' });

            pdf.setDrawColor(...COLOR_MARCA_VERDE);
            pdf.setLineWidth(1);
            pdf.line(MARGEN, 38, anchoPagina - MARGEN, 38);

            pdf.setFontSize(11);
            pdf.setTextColor(30, 30, 30);
            pdf.setFont(undefined, 'bold');
            pdf.text('Proveedor:', MARGEN, 47);
            pdf.setFont(undefined, 'normal');
            pdf.text(String(proveedor), MARGEN + 28, 47);

            pdf.setFont(undefined, 'bold');
            pdf.text('Emitido por:', MARGEN, 53);
            pdf.setFont(undefined, 'normal');
            pdf.text(NOMBRE_EMPRESA, MARGEN + 28, 53);

            return dibujarEncabezadoTabla_(60);
          }

          let y = encabezadoPagina_();
          pdf.setFont(undefined, 'normal');
          pdf.setFontSize(9);

          filasValidas.forEach((f, idx) => {
            const esBulto = f.unidad === 'bultos' && f.bulto;
            const cantidadTexto = esBulto ? `${Math.ceil(f.cantidadPedir / f.bulto.unidadesPorBulto)}` : `${f.cantidadPedir}`;
            const unidadTexto = esBulto ? `Caja(s) x${f.bulto.unidadesPorBulto}` : 'Unidades';

            const lineasDescripcion = pdf.splitTextToSize(String(f.producto), COL_DESCRIPCION.w - 4);
            const alturaFila = Math.max(7, lineasDescripcion.length * 4.2 + 2.5);

            // Salto de página si no entra la fila completa
            if (y + alturaFila > altoPagina - 20) {
              pdf.addPage();
              y = dibujarEncabezadoTabla_(14);
              pdf.setFont(undefined, 'normal');
              pdf.setFontSize(9);
            }

            if (idx % 2 === 1) {
              pdf.setFillColor(245, 248, 244);
              pdf.rect(MARGEN, y, ANCHO_UTIL, alturaFila, 'F');
            }

            pdf.setTextColor(30, 30, 30);
            pdf.text(String(f.codigo), COL_CODIGO.x + 2, y + 5);
            pdf.text(lineasDescripcion, COL_DESCRIPCION.x + 2, y + 5);
            pdf.text(cantidadTexto, COL_CANTIDAD.x + COL_CANTIDAD.w / 2, y + 5, { align: 'center' });
            pdf.text(unidadTexto, COL_UNIDAD.x + COL_UNIDAD.w / 2, y + 5, { align: 'center' });

            pdf.setDrawColor(225, 225, 225);
            pdf.setLineWidth(0.2);
            pdf.line(MARGEN, y + alturaFila, MARGEN + ANCHO_UTIL, y + alturaFila);

            y += alturaFila;
          });

          y += 10;
          if (y > altoPagina - 20) { pdf.addPage(); y = 20; }
          pdf.setFontSize(10);
          pdf.setTextColor(60, 60, 60);
          pdf.text(`Total de líneas: ${filasValidas.length}`, MARGEN, y);

          // Pie de página en todas las hojas generadas
          const totalPaginas = pdf.internal.getNumberOfPages();
          for (let p = 1; p <= totalPaginas; p++) {
            pdf.setPage(p);
            pdf.setFontSize(8);
            pdf.setTextColor(150, 150, 150);
            pdf.text(`Generado automáticamente por ${NOMBRE_EMPRESA} — ${ahora.toLocaleString('es-AR')}`, MARGEN, altoPagina - 10);
          }

          pdf.save(`${numeroOC}_${proveedor.replace(/\s+/g, '_')}.pdf`);
        } catch (err) {
          mostrarToast('Error generando el PDF: ' + err.message, true);
        } finally {
          btn.disabled = false;
          btn.textContent = '📄 Descargar PDF para el proveedor';
        }
      }

          // ---------------- FILTRO POR PROVEEDOR EN LA PANTALLA PRINCIPAL ----------------
      // Mismo cache/lógica que la vista Compras, pero embebido en la
      // pantalla de conteo — así el que cuenta no tiene que salir de acá
      // para ver "qué tiene tal proveedor" cuando Compras le pide
      // actualizar el stock de alguno puntual.
      poblarSelectProveedores_(document.getElementById('cn_selectProveedorInline'));

      document.getElementById('cn_selectProveedorInline').addEventListener('change', async () => {
        const cont = document.getElementById('cn_listaProveedorInline');
        const buscador = document.getElementById('cn_buscarProductoInline');
        const proveedor = document.getElementById('cn_selectProveedorInline').value;

        if (!proveedor) {
          buscador.style.display = 'none';
          cont.innerHTML = '';
          document.getElementById('cn_contadorProveedorInline').textContent = '';
          return;
        }
        buscador.style.display = 'block';

        if (!productosComprasMaestro) {
          cont.innerHTML = '<div class="cargando">Cargando productos...</div>';
          try { await cargarProductosCompras_(); } catch (err) { return; }
        }
        renderizarListaProveedorInline_();
      });

      document.getElementById('cn_buscarProductoInline').addEventListener('input', renderizarListaProveedorInline_);

      document.getElementById('cn_btnActualizarProveedorInline').addEventListener('click', async () => {
        const cont = document.getElementById('cn_listaProveedorInline');
        cont.innerHTML = '<div class="cargando">Actualizando...</div>';
        try { await cargarProductosCompras_(); } catch (err) { return; }
        renderizarListaProveedorInline_();
      });

      function renderizarListaProveedorInline_() {
        const proveedor = document.getElementById('cn_selectProveedorInline').value;
        const texto = document.getElementById('cn_buscarProductoInline').value.trim().toLowerCase();
        const cont = document.getElementById('cn_listaProveedorInline');
        const contador = document.getElementById('cn_contadorProveedorInline');
        if (!proveedor || !productosComprasMaestro) return;

        const filas = filtrarProductosMaestro_(proveedor, texto);
        contador.textContent = `${filas.length} producto(s)`;
        cont.innerHTML = filas.length
          ? filas.map(filaComprasHtml_).join('')
          : '<div class="empty-state">Sin resultados</div>';
      }

      // Distingue "nunca se contó" (el campo stockTotal no existe en el
      // documento) de "se contó y dio 0" (stockTotal existe y vale 0) —
      // son dos situaciones bien distintas para Compras: la primera dice
      // "andá a contarlo", la segunda dice "andá a pedirlo".
      function estadoStock_(p) {
        if (!p.tieneAlgunaPosicion) return { texto: 'No contado', clase: 'no-contado' };
        const stockTotal = Number(p.stockTotal) || 0;
        if (stockTotal === 0) return { texto: 'Sin stock', clase: 'sin-stock' };
        return { texto: String(stockTotal), clase: 'con-stock' };
      }

      function filtrarProductosMaestro_(proveedor, texto) {
        if (!productosComprasMaestro) return [];
        let filas = productosComprasMaestro;
        if (proveedor) filas = filas.filter(p => p.proveedor === proveedor);
        if (texto) filas = filas.filter(p => p.producto.toLowerCase().includes(texto) || p.codigo.toLowerCase().includes(texto));
        return filas.slice().sort((a, b) => a.producto.localeCompare(b.producto, 'es'));
      }

      function filaComprasHtml_(p) {
        const estado = estadoStock_(p);
        return `<div class="fila-compras" onclick="window.__contarDesdeCompras('${escapeHtml(p.codigo).replace(/'/g, "\\'")}')" style="cursor:pointer;">
          <div class="info">
            <div class="nombre">${escapeHtml(p.producto)}</div>
            <div class="detalle">${escapeHtml(p.codigo)}${p.proveedor ? ' · ' + escapeHtml(p.proveedor) : ''}${p.posicionPrincipal ? ' · pos: ' + escapeHtml(p.posicionPrincipal) : ''}</div>
          </div>
          <div class="estado-stock ${estado.clase}">${estado.texto}</div>
        </div>`;
      }

      function renderizarVistaCompras_() {
        const cont = document.getElementById('cn_comprasContenido');
        const contador = document.getElementById('cn_contadorCompras');
        if (!productosComprasMaestro) return;

        const proveedor = document.getElementById('cn_selectProveedorCompras').value;
        const texto = document.getElementById('cn_buscarProductoCompras').value.trim().toLowerCase();
        const filas = filtrarProductosMaestro_(proveedor, texto);
        contador.textContent = `${filas.length} producto(s)`;

        cont.innerHTML = filas.length
          ? filas.map(filaComprasHtml_).join('')
          : '<div class="empty-state">Sin resultados</div>';
      }

      // Tocar un producto de la lista de Compras cierra esa vista y lo abre
      // directo en la pantalla de conteo, como si se acabara de escanear —
      // así el que cuenta puede ir tocando uno por uno los que le pasaron
      // de un proveedor, sin tener que volver a buscarlos a mano.
      window.__contarDesdeCompras = function(codigo) {
        abrirConteo(); // cambia a la pestaña Conteo de la pantalla Stock
        buscarProducto(codigo);
      };

      function escapeAttrJs(str) { return String(str).replace(/'/g, "\\'"); }

  return {
    abrirCompras: abrirVistaCompras,
    abrirArmarPedido: abrirArmarPedido,
    // apaga la cámara si alguien se va de la pantalla con el escáner prendido
    detenerEscaneres: () => { try { detenerEscaneo(); } catch (e) {} try { detenerEscaneoBulto(); } catch (e) {} }
  };
}
